        "id": "cat_01_13",
        "code": "01.13",
        "majorId": "01",
        "mediumId": "01.13",
        "smallId": "",
        "name": "水产业",
        "description": "本中类包括“水产业”(或水产养殖业),即涉及水生生物(鱼类、软体动物、甲壳类动物、植物、鳄鱼、短吻鳄和两栖动物)的养殖或饲养(包括收获)的生产过程，该过程中使用技术(例如定期放鱼苗、喂养和天敌防护)解决环境自然承载力的问题以增加生物的产量。\n养殖/饲养是指上述生物蓄养到被捕捞的幼体和/或成熟阶段。此外，“水产业”的整个饲养或养殖阶段直至收获过程中，个体生物所有权包括个人所有、企业所有或政府所有的情况。",
        "includes": [],
        "excludes": [],
        "text_unit": "01 01.13 水产业 本中类包括“水产业”(或水产养殖业),即涉及水生生物(鱼类、软体动物、甲壳类动物、植物、鳄鱼、短吻鳄和两栖动物)的养殖或饲养(包括收获)的生产过程，该过程中使用技术(例如定期放鱼苗、喂养和天敌防护)解决环境自然承载力的问题以增加生物的产量。 养殖/饲养是指上述生物蓄养到被捕捞的幼体和/或成熟阶段。此外，“水产业”的整个饲养或养殖阶段直至收获过程中，个体生物所有权包括个人所有、企业所有或政府所有的情况。",
