            "description": "本小类包括：\n一海水渔业养殖，包含海洋观赏鱼类养殖；\n一双壳贝苗(牡蛎贻贝等)、小龙虾、对虾后期幼体、鱼苗和鱼种的生产；\n一紫菜及其他可食用海藻的养殖。\n一甲壳类动物、双壳类动物、其他软体动物和其他海水中水生动物的养殖。\n本小类还包括：\n一半咸水域水产养殖活动；\n一在养殖箱和蓄水池中注入咸水的水产养殖活动；\n一鱼类(海洋)孵化场的运营；\n一海洋虫类养殖场的运营。",
            "includes": [],
