    "name": "采矿业和采石业",
    "description": "采矿及采石业包括对固态(煤和矿石)、液态(石油)或气态(天然气)天然矿物的开采。可以通过不同的开采方式，如地下或露天开采、钻井作业、海底采矿等。 本大类包括以准备销售天然原料为目的的附加活动，例如破碎、粉碎、清洗、干燥、分拣、精选矿石，天然气液化和固态燃料的附聚等。这些操作通常由资源开采单位和/或其他就近的单位完成。 以主要矿物生产为基础将采矿进一步划分了矿物燃料(硬煤、褐煤、石油、天然气)的采掘和开采；金属矿石、各类矿物和石矿产品的开采。 本大类的某些技术操作，特别是关于提取烃类化合物，也将引出单独的工业服务类别(采矿、采石、石油天然气开采支持服务)。",
