            "text_unit": "02 02.06 02.06.02 其他非铁金属矿石的开采 以下列有非铁金属为主要价值的矿石开采和制备：铝(铝土矿)、铜、铅、锌、锡、锰、铬、镍、钴、钼、钽、钒等；贵金属：金、银、铂。 铀和钍矿石的开采和制备，见02.06.01; 氧化铝的生产，见17.04.02; 铜锍或镍锍的生产，见17.04.04、17.04.05。",
