    "description": "本大类包括纺织品的制造和服装的制造。纺织品制造包括纺织用纤维的备制和纺纱，以及纺织织造、纺织品和服装的整理，不包括服装外的纺织制成品(如日用亚麻织品、毛毯、小地毯、绳索等)的制造。天然纤维的种植归类于01大类，而合成纤维的制造是一个化学过程，归类于12.06.00小类。服装的制造包括各种制衣业(成衣或定做),用任何材料(例如皮革、织物、针织和钩编织物等)制成不同款式服装(例如男、女或儿童的外衣、内衣；工作服、都市装或便装等)和配饰。分类中不区分成人服装和儿童服装或现代服装和传统服装。服装的制造还包括毛皮服装制造。",
