    "name": "木材及木制品",
    "description": "本大类包括木制品的制造，例如木材、胶合板、饰面薄板、木容器、木地板、木桁架和预制木建筑。生产过程包括：将切成段的原木、或可被进一步切削、或已用车床或其他定型工具定型的木料，通过锯切、刨削、成型、层压、组装制成木产品。这些木料或其他改变形状的木料也可以随后被刨平或打磨，并组装成成品，例如木容器。除锯木外，本大类主要根据制造的特定产品细分。本大类不包括家具制造(见23.01),及木制配件及类似制品的安装(见28.08.02、28.08.03、28.08.05)。",
