    "id": "cat_07",
    "code": "07",
    "majorId": "07",
    "mediumId": "",
    "smallId": "",
    "name": "纸浆、纸及纸制品",
    "description": "本大类包括纸浆、纸张和加工纸制品的制造。因为这些产品的制造构成了一系列前后连接的过程，故将其合并在一大类。在一个单元中通常会发生多项活动。本质上有三项活动：纸浆的制造涉及将木材中的纤维与其他成分分离、或将用过的纸溶解并脱墨，并添加少量试剂，以加强纤维的捆束力；纸张的制造包括将纸浆释放到移动的丝网上，以形成连续的纸张；加工纸制品则由纸和其他材料通过各种技术制造。纸制品可以包括印刷(如壁纸、礼品包装等),但印刷的信息不是主要目的。07.01中类包含了纸浆、纸和大部分纸板的生产，而其他类别包括深加工的纸和纸制品的制造。",
    "includes": [],
    "excludes": [],
    "text_unit": "07 纸浆、纸及纸制品 本大类包括纸浆、纸张和加工纸制品的制造。因为这些产品的制造构成了一系列前后连接的过程，故将其合并在一大类。在一个单元中通常会发生多项活动。本质上有三项活动：纸浆的制造涉及将木材中的纤维与其他成分分离、或将用过的纸溶解并脱墨，并添加少量试剂，以加强纤维的捆束力；纸张的制造包括将纸浆释放到移动的丝网上，以形成连续的纸张；加工纸制品则由纸和其他材料通过各种技术制造。纸制品可以包括印刷(如壁纸、礼品包装等),但印刷的信息不是主要目的。07.01中类包含了纸浆、纸和大部分纸板的生产，而其他类别包括深加工的纸和纸制品的制造。",
