            "text_unit": "07 07.02 07.02.03 纸制文具的制造 即用打印和书写纸的制造； 即用计算机打印纸的制造； 即用自显复写纸的制造； 即用复写蜡纸和碳粉复写纸的制造； 即用胶纸或胶粘纸的制造； 信封和明信片的制造； 教育和商务文具(笔记本、活页夹、登记薄、会计账簿、业务表格等)的制造，其上印刷的信息并非主要特征； 盒、袋、夹和包含各类纸文具的书写用套装的制造。 纸制品的印刷，见09.01。",
            "children": []
