    "description": "本大类包括产品(例如报纸、书籍、期刊、商业表格、贺卡和其他资料)的印刷，以及相关的支持性活动(例如装订、制版服务和数码成像)。这里的支持活动是印刷业的一个组成部分，而且印刷产品(印制版本、精装书、计算机磁盘或文件)作为印刷业的组成部分也几乎总是由这些活动提供的。印刷过程包括了各种将图像从碟片、屏幕或者电脑文件中转移到另一种媒介，例如纸、塑料、金属、纺织制品或木料的方法。这些方法中最突出的是通过平版印刷、凹版印刷、丝网印刷或柔性版印刷，将影像从碟片或屏幕转移到另一媒介。通常计算机文件用以直接驱动印刷机械或静电的及其他类型的设备(数字或非接触式印刷)产生影像。尽管印刷及出版可以由同一单位完成(例如报纸),但这些不同类活动在同一实际地点完成的情况越来越少了。本大类还包括记录媒介，如CD、录像、光盘或磁带上的软件、记录等的复制。本大类不包括出版活动。",
