    "description": "本大类包括将原油和原煤转变为可用产品。主要过程是石油精炼，即通过裂解和蒸馏技术将原油分离为各种成分的产品。 本大类包括气体的制造，例如炼油厂生产乙烷、丙烷和丁烷。 本大类还包括自营特色产品(例如焦炭、丁烷、丙烷、汽油、煤油、燃料油等)的制造，以及加工服务(如定制精炼)。 本大类不包括其他单位中上述气体的制造(12.01.04), 工业气体的制造(12.01.01),天然气(甲烷、乙烷、丙烷或丁烷)的开采(02.04.00),以及除石油气外燃料气体(例如煤气、水煤气、发生炉煤气、煤气厂煤气)的制造(26.01.01)。由精炼石油制造石化产品属于12大类。",
