            "text_unit": "12 12.01 12.01.03 其他无机基础化学品的制造 本小类包括利用基本过程制造化学品。这些过程的产出通常是分离的化学元素或分离的且化学成分确定的化合物。 化学元素的制造(除了工业气体和基础金属): 一硝酸以外的无机酸制造； 一碱、碱液和氨以外其他无机碱的制造； 一其他无机化合物的制造； 一黄铁矿的煅烧； 一蒸馏水的制造。 铀和钍矿石的浓缩。 工业气体的制造，见12.01.01: 氮肥和含氮化合物的制造，见12.01.05; 氨的制造，见12.01.05; 氯化铵的制造，见12.01.05; 亚硝酸钾和硝酸钾的制造，见12.01.05; 碳酸铵的制造，见12.01.05; 芳香蒸馏水的制造，见12.05.03; 基础金属的制造，见17.01～17.05。",
