    "mediumId": "",
    "smallId": "",
    "name": "机械及设备",
    "description": "本大类包括机械设备的制造、维修与安装，以及武器弹药及军用作战车辆的制造。\n机械设备的制造包括制造用于单独对材料进行机加工、热加工或处理(如装卸、喷洒、称重、打包等)的机械和设备，包括产生和应用动力的机械部件，以及任何专门制造的主要零部件。本大类包括固定、移动或手持装置的制造，不论这些装置是用于工业、建筑与土木工程、农业、军事或家用。场所特定区域内，客、货运输用特殊设备的制造也属于机械制造类。\n机械设备区分出了特殊用途机械的制造与通用机械的制造。还包括其他类别未包括的一些专用机械的制造，不论这些机械是否用于制造过程，如游乐场娱乐设备、自动保龄球馆设备等。\n本大类不包括通用金属制品、相关控制设备、计算机设备、测量和测试设备、配电及控制装置和通用机动车辆的制造。",
    "includes": [],
    "excludes": [],
