            "text_unit": "18 18.02 18.02.06 其他未另分类的通用机械的制造 一称重设备的制造(高灵敏度实验室天平除外): ◆家用和商用磅称、台称、连续称量设备、地磅、称砣等。 —液体过滤或净化机械和装置的制造； 一液体或粉末喷射、撒布或喷洒设备的制造： ◆喷枪、灭火器、喷砂机、蒸汽清洗机等。 一打包和包装机械的制造： ◆装填、封口、密封、封盖或贴标签的机械等。 一用于清洗或烘干瓶子和充气饮料制作的机械的制造； 一炼油厂、化工业、饮料业等使用的蒸馏或精馏设备的制造 ； 一气体发生器的制造； 一压延机或其他轧制机及其滚筒(用于金属和玻璃的除外)的制造； 一离心机(乳脂分离器和衣服甩干机除外)的制造； 一由组合材料或数层同样材料制成的衬垫和类似接合物的制造； 一自动售货机的制造； 一水平仪、卷尺和类似手工工具、技师用精密工具(光学工具除外)的制造； 一非电动焊接与钎焊设备的制造； 一用循环水直接冷却的冷却塔和类似设备的制造。 —高灵敏度(实验室用)天平的制造，见19.05.01; 一家用冷冻或冷藏设备的制造，见19.13.01; 一家用风扇的制造，见19.13.01; —电焊和钎焊设备的制造，见19.14.00; —农用喷雾机械的制造，见18.03.00; 一金属或玻璃轧机及其滚筒的制造，见18.05.01,、18.05.07; 一农用烘干机的制造，见18.05.03; 一食品过滤或净化机械的制造，见18.05.03; 一乳脂分离器的制造，见18.05.03; —商用干衣机的制造，见18.05.04; 一纺织品印刷机械的制造，见18.05.04。",
