    "description": "本大类包括计算机、计算机外部设备、通信设备和类似电子产品的制造，以及这些产品元器件的制造。其生产过程特征为集成电路的设计和应用，以及高度专业化的微型化技术的应用。\n本大类还包含电子消费品，测量、检测与导航设备，放射、电子医学及电治疗设备，光学仪器及设备，以及磁性和光学媒体的制造。\n本大类还包括发电、配电和使用电力的产品的制造，也包括电力照明设备、信号设备和家用电器的制造。\n本大类还包括电子和光学设备的修理、电气设备的修理以及计算机及其外部设备和通信设备的修理和维护。",
