            "majorId": "19",
            "mediumId": "19.02",
            "smallId": "19.02.00",
            "name": "计算机及其外部设备的制造",
            "description": "本小类包括电子计算机，例如大型计算机主机、台式计算机、笔记本计算机和计算机服务器，以及计算机外部设备，例如存储设备和输入/输出设备(打印机、显示器、键盘)的制造和/或组装。计算机可为模拟、数字或混合型。最常见的数字计算机是能完成以下所有活动的装置：(1)存储运行程序和程序运行直接需要的数据；(2)可以依照用户的要求自由编程；(3)执行用户规定的算术运算；(4)不需人工干预，执行处理程序，该程序运行过程中要求计算机通过逻辑判定来修正运行。模拟计算机有模拟数学模型的能力，至少包括模拟控制和编程单元。",
            "includes": [
              "一台式计算机的制造； 一笔记本计算机的制造；",
              "一大型计算机的制造； 一手持式计算机(如PDA)的制造；",
              "一磁盘驱动器、闪存驱动器和其他存储设备的制造； 一 光 盘 ( 如 C D - R W 、 C D - R O M 、D V D - R O M 、DVD-RW)驱动器的制造；",
              "一打印机的制造； 一显示器的制造；",
              "一键盘的制造； 一所有类型鼠标、控制杆和轨迹球附件的制造；",
              "一专用计算机终端的制造； 一计算机服务器的制造；",
              "一扫描仪，包括条码扫描仪的制造； 一智能卡读卡器的制造；",
              "一虚拟现实头盔的制造；一计算机投影仪(视频播放设备)的制造。",
              "一非机械式计算机终端的制造，如自动柜员机(ATM)、销售点终端机(POS机);",
              "一多功能办公设备的制造，具有以下功能中的两个或更多：打印、扫描、复印、传真。"
            ],
