    "description": "本大类包括建筑物和土木工程的一般和专门建设活动。包括了新建、改建、扩建、维修、现场安装预制建筑物或结构件，以及临时性建造。 一般施工是指全部住宅楼、办公楼、商店和其他公共和公用事业建筑、农场建筑等的建造，例如高速公路、街道、桥梁、隧道、铁路、机场、港口和其他水利工程项目、灌溉系统、污水处理系统、工业设施、管道和电力线路、体育设施等的等建设工程的建造。 这类工程可以自己承建，或者以合同形式承包出去。工程的一部分，有时甚至整个工程都可以分包出去。对某个建筑项目全面负责的单位也归于本类。 此外本大类还包括建筑物及工程设施的修理。 本大类包括房屋建筑的全部建设(28.01～28.02)、土木工程的全部建设(28.03～28.05),以及只作为施工过程一部分的专门施工活动(28.06～28.09)。 配备操作人员的施工设备的出租，依据该设备实施的特定建筑活动分类。 本大类还包括为了后期的销售，通过整合资金、技术和物质手段完成的建筑或土木工程建设项目的开发。如果这些活动不是为了建设项目的后期销售，而是经营它们(例如，这些建筑物的出租，建筑内的制造活动),则不归类于本类，而是根据其经营活动，即房地产、制造业等分类。",
    "includes": [],
    "excludes": [],
    "text_unit": "28 建设业 本大类包括建筑物和土木工程的一般和专门建设活动。包括了新建、改建、扩建、维修、现场安装预制建筑物或结构件，以及临时性建造。 一般施工是指全部住宅楼、办公楼、商店和其他公共和公用事业建筑、农场建筑等的建造，例如高速公路、街道、桥梁、隧道、铁路、机场、港口和其他水利工程项目、灌溉系统、污水处理系统、工业设施、管道和电力线路、体育设施等的等建设工程的建造。 这类工程可以自己承建，或者以合同形式承包出去。工程的一部分，有时甚至整个工程都可以分包出去。对某个建筑项目全面负责的单位也归于本类。 此外本大类还包括建筑物及工程设施的修理。 本大类包括房屋建筑的全部建设(28.01～28.02)、土木工程的全部建设(28.03～28.05),以及只作为施工过程一部分的专门施工活动(28.06～28.09)。 配备操作人员的施工设备的出租，依据该设备实施的特定建筑活动分类。 本大类还包括为了后期的销售，通过整合资金、技术和物质手段完成的建筑或土木工程建设项目的开发。如果这些活动不是为了建设项目的后期销售，而是经营它们(例如，这些建筑物的出租，建筑内的制造活动),则不归类于本类，而是根据其经营活动，即房地产、制造业等分类。",
