            "description": "本小类包括：\n 一金属和非金属废旧材料及回收材料的批发，包括对旧货(如汽车等)进行收集、分类、分离、剥离等以获取可再利用的零件，打包和重新包装、储存和发送，但对物品不进行实际改造。此外，购进和出售的废料具有残余价值。\n本小类还包括：\n 一将车辆、计算机、电视和其他设备进行拆解以获取可用零部件再出售。",
