            "text_unit": "31 31.13 31.13.05 其他运输支持活动 本小类包括： 一 货运代理； 一铁路运输、公路运输、海运或空运的组织安排； 一团体或个人的货物托运(包括货物分拣、交付和托 运分组)的组织； 一运输单据和运货单的发布和获取； 一报关代理活动； 一海运货物承运和空中货运代理活动； 一船舶和飞机舱位经纪； 一货物处理，例如在运输过程仅为保护货物而采取的 临时装箱、开箱、取样、称重的处理等。 本小类还包括： 一快递的活动，见31.15.00; 一提供汽车、船舶、航空和运输保险，见32.05.02; 一旅行社的活动，见39.09.01; 一旅游经营者的活动，见39.09.02; 一游客协助活动，见39.10.00。",
