            "text_unit": "32 32.01 32.01.01 中央银行 本小类包括： 一发行和管理国家货币； 一监测和控制货币供应量； 一接受用于金融机构之间结算的存款； 一监督银行运营； —掌管该国的外汇储备； 一代表政府的银行。 中央银行的活动因制度原因而有不同。",
