        "children": [
          {
            "majorId": "32",
            "mediumId": "32.03",
            "smallId": "32.03.00",
            "name": "信托、基金及类似金融实体",
            "description": "本小类包括此类法律实体，其代表股东或受益人，将不\n由其管理的证券或其他金融资产建立证券/资产池。证券\n投资组合根据客户要求为达到特定投资特性定制，例如多\n样化、风险、投资收益率、价格波动性等。这些实体可以\n获得利息、红利和其他资产收入，但在劳务中不会发生或\n极少发生雇用关系且没有收入。\n 本小类包括：\n 一开放式投资基金；\n 一封闭式投资基金；\n —单位投资信托基金；\n 一根据委托书、遗嘱或代理协议代表受益人管理的信\n 托基金、房地产账户或代理账户。",
            "excludes": [
              "一从产品或服务销售中营利的基金和信托基金，根据\n 其主要活动见其他类；",
              "一控股公司的活动，见32.02.00;",
              " —养老基金，见32.07.00;",
              "一基金管理，见32.10.00。"
            ],
            "text_unit": "32 32.03 32.03.00 信托、基金及类似金融实体 本小类包括此类法律实体，其代表股东或受益人，将不 由其管理的证券或其他金融资产建立证券/资产池。证券 投资组合根据客户要求为达到特定投资特性定制，例如多 样化、风险、投资收益率、价格波动性等。这些实体可以 获得利息、红利和其他资产收入，但在劳务中不会发生或 极少发生雇用关系且没有收入。 本小类包括： 一开放式投资基金； 一封闭式投资基金； —单位投资信托基金； 一根据委托书、遗嘱或代理协议代表受益人管理的信 托基金、房地产账户或代理账户。 一从产品或服务销售中营利的基金和信托基金，根据 其主要活动见其他类； 一控股公司的活动，见32.02.00; —养老基金，见32.07.00; 一基金管理，见32.10.00。",
            "id": "cat_32_03_00",
            "code": "32.03.00",
            "children": []
          }
        ]
