            "name": "知识产权和类似产品的租用(版权作品除外)",
            "description": " 本小类包括通过向知识产权产品和类似产品的所有者\n(如资产所有者)支付特许费用或许可费用后，允许他人使\n用其产品的活动。对这些产品的租赁可采用各种形式，如\n允许复制、在后续加工或产品生产中使用、企业特许经营\n等。当时其所有者可能已经创造出或还未创造出这些产品。\n本小类包括：\n 一知识产权产品的租赁(版权作品除外，如书籍或软\n 件 );\n 一从下述使用过程中收取使用费或许可费：\n ◆有专利的实体；\n ◆商标或服务商标；\n ◆品牌名称；\n ◆矿产勘探和评价；\n ◆特许经营协议。\n 本小类不包括：\n —获得版权和出版，见08.01、08.02、33.01、39.05;\n 一生产、复制和发行版权作品(书籍、软件、电影),\n 见08.01、08.02、33.01、39.05;\n 一房地产租赁，见32.12.00;\n 一有形产品(资产)的租赁，见32.14～32.16。",
