            "description": "本小类包括生物技术的研究与实验性开发：\n—DNA/RNA:基因组学、药物基因组学、基因探测、\n 基因工程、DNA/RNA的测序/合成/增容、基因表\n 达谱，以及应用反义技术；\n 一蛋白质和其他分子：排序/合成/设计蛋白质和肽(包\n 括大分子荷尔蒙),改善大分子药物传递方法，蛋白质\n 组、蛋白质的分离和纯化，标记，识别细胞受体；\n 一细胞和组织培养与工程学：细胞/组织培养，组织\n 工程(包括组织支架和生物医学工程),细胞融合，\n 疫苗/免疫增强剂，胚胎操纵；\n一生物处理技术：用生物反应器发酵，生物加工，生\n 物浸出，生物制浆，生物漂白，生物脱硫，生物修\n 复，生物过滤和植物修复；\n一基因和RNA载体：基因治疗，病毒载体；\n 一生物信息学：关于基因组、蛋白质序列数据库的建\n 设，复杂生物过程模型(包括系统生物学);\n 一纳米生物技术：运用纳米/微制造工具和工艺，建立\n 研究生物系统以及用于药物输送、诊断等的设备。",
