    "name": "公共行政管理",
    "description": " 本大类包括带有政府性质，通常由公共行政管理部门执行\n的活动。这包括法律和相应法规的制定及司法解释，以及在\n此基础上的公共管理事务、立法活动、税收、国防、公共秩\n序和公共安全、移民服务、外交事务和政府管理事务。\n 根据活动具有上述的属性列入本大类，而不是根据机构的\n法律地位确定其是否属于本类。也就是说，其他类别的活动\n即使由公共部门完成，也不能归于本类。例如，学校系统的\n行政管理(即监管、检查、课程设置)归于本类，但教学本\n身归入37大类，同样监狱医院和军事医院归入38大类。类\n似的，本大类中的一些活动也可以由非政府单位实施。\n 本大类还包括强制性社会保障活动。",
    "text_unit": "36 公共行政管理 本大类包括带有政府性质，通常由公共行政管理部门执行 的活动。这包括法律和相应法规的制定及司法解释，以及在 此基础上的公共管理事务、立法活动、税收、国防、公共秩 序和公共安全、移民服务、外交事务和政府管理事务。 根据活动具有上述的属性列入本大类，而不是根据机构的 法律地位确定其是否属于本类。也就是说，其他类别的活动 即使由公共部门完成，也不能归于本类。例如，学校系统的 行政管理(即监管、检查、课程设置)归于本类，但教学本 身归入37大类，同样监狱医院和军事医院归入38大类。类 似的，本大类中的一些活动也可以由非政府单位实施。 本大类还包括强制性社会保障活动。",
