            "text_unit": "36 36.02 36.02.03 司法活动 本小类包括： 一民事和刑事法庭、军事法庭和司法系统的管理和运 作，包括代表政府或由政府出资或提供服务的法律 代理或咨询； 一宣判和解释法律； 一民事诉讼的仲裁； 一监狱管理和改正服务的提供，包括犯人的改过服 务，无论这些是由政府单位管理和运作，或是在合 同或收费的基础上由私人单位进行管理和运作。 一民事、刑事和其他案件的法律咨询和代理，见35.01.00; 一监狱学校的活动，见37大类； 一监狱医院的活动，见38.01.00。",
