        "text_unit": "37 37.05 其他教育 本中类包括常规继续教育、职业继续教育，以及以职 业、爱好或个人发展为目的的各类培训。 本中类不包括37.01～37.04(即：学前教育、初等教 育、中等教育或更高等级教育)中所述的教育活动。本中 类包括训练营和学校向个体或团体提供的体育运动教学活 动、提供外语教学以及艺术、戏剧、音乐或其他特殊教学 与培训，非37.01～37.04中所指的教育。",
