    "description": " 本大类包括提供保健及社会工作。这些活动包括的范围很\n广，从在医院和其他场所由训练有素的医务专业人员提供医\n疗保健活动，到仍含有一定程度医疗保健性质的留宿护理活\n 动，再到没有任何专业医护人员参与的社会工作活动。\n 本大类也包括兽医活动。",
    "text_unit": "38 健康和社会工作 本大类包括提供保健及社会工作。这些活动包括的范围很 广，从在医院和其他场所由训练有素的医务专业人员提供医 疗保健活动，到仍含有一定程度医疗保健性质的留宿护理活 动，再到没有任何专业医护人员参与的社会工作活动。 本大类也包括兽医活动。",
