            "name": "医院活动",
            "description": " 本小类包括：\n 一短期医院或长期医院的活动，即全科医院(如社区\n 和地区医院、非营利组织医院、大学医院、军事基\n 地和监狱医院)和专科医院(如精神健康和药品滥\n 用医院、传染病院、妇产医院、专科疗养院)的医\n 疗、诊断和治疗活动。\n 这些活动主要是针对住院病人，并在医生的直接监督下\n进行，包括：\n ◆医务人员及辅助医务人员的服务；\n ◆实验室和技术设施的服务，包括放射性和麻醉服务；\n ◆急诊室服务；\n ◆计划生育中心提供的诸如绝育和终止妊娠等住院\n 医疗服务。",
