            "text_unit": "38 38.03 38.03.00 其他人类保健活动 本小类包括： 一由医院、医生或牙医之外提供的人类保健活动： ◆在验光、水疗、医疗按摩、职业治疗、语言障碍 矫正、脚病治疗、顺势疗法、脊椎推拿疗法、针 灸等领域的护士、助产士、理疗师或其他辅助助医 务人员的活动。 这些活动可能在附属于企业、学校、养老院、劳工组织 和互助组织的卫生所进行，也可能在医院之外的留宿保健 机构进行，也可以在个人开办的诊室、病人家中或其他场 所进行。 本小类还包括： 一牙科辅助医务人员如牙科理疗师，学校牙科护士和 牙科保健师的活动，但这些人需由牙医定期监督指 导(可以采用远程方式); 一如下医学实验室的活动： ◆X一射线实验室及其他影像诊断中心； ◆血液分析实验室。 一血库、精子库和移植器官库的活动； 一以各种运输形式(包括飞机)紧急救护运送病人。 这些服务通常在紧急医疗时提供。 一由牙科实验室进行的假牙、牙托和假牙器具的制 造，见23.06.00; 一在既无医务人员也无救生设备的情况下转移病人， 见31.01～31.11; 一非医学实验室检测，见34.02.00; 一在食品卫生领域的检测活动，见34.02.00; 一医院活动，见38.01.00; —医生和牙科诊疗活动，见38.02; —留宿护理设施，见38.04。",
            "id": "cat_38_03_00",
