    "text_unit": "15 15.03 15.03.01 陶瓷砖和陶瓷板的制造 —非耐火灶台或墙面贴砖、马塞克瓷块等的制造； 一非耐火陶瓷薄片和铺砌材料的制造。 一人造石材(如人造大理石)的制造，见14.02.03; 一耐火陶瓷制品的制造，见15.02.00; 一陶瓷砖、屋顶瓦的制造，见15.03.02。"
