    "text_unit": "18 18.02 18.02.04 动力驱动手工工具的制造 一手工工具的制造，自带电源或非电马达或气动驱动，诸如： ◆圆锯或往复锯； ◆ 链 锯 ； ◆钻和冲击钻； ◆手持电动磨砂机； ◆气动射钉枪； ◆缓冲器； ◆刨槽机； ◆研磨机； ◆装订机； ◆气动铆钉枪； ◆ 手 刨 ； ◆剪切机和下料机； ◆冲击扳手； ◆火药射钉枪。 一手工工具中可互换件的制造，见17.11.03; 一手持电动钎焊和焊接设备的制造，见19.14.00。"
