    "text_unit": "19 19.03 19.03.00 通信设备的制造 本小类包括用有线或无线方式(例如通过无线电和电视广播以及无线通信设备)传送电子信号的电话和数据通信设备的制造。 一办公用中央交换设备的制造； 一无绳电话的制造； 一专用小交换机(PBX)设备的制造； 一电话和传真设备的制造，包括电话答录机； —数据通信设备的制造，如网桥、路由器和网关； 一发射和接收天线的制造； 一有线电视设备的制造； 一传呼机的制造； 一手提电话的制造； 一移动通信设备制造； 一无线电、电视和广播设备的制造，包括电视摄像机； 一调制解调器、载波设备的制造； 一发送信号到控制台的防盗和防火报警系统的制造； 一无线电和电视发射器的制造； 一使用红外信号(如远程控制)的通信装置的制造。 一用于通信设备(包括内置/外置计算机调制解调器)的电子元器件和组件的制造，见19.01; 一带元件电子板的制造，见19.01.02; 一计算机和计算机外部设备的制造，见19.02.00; 一消费类音频和视频设备的制造，见19.04.00; —GPS装置的制造，见19.05.01; 一电子记分牌的制造，见19.14.00; 一交通信号灯的制造，见19.14.00。"
