    "text_unit": "19 19.04 19.04.00 消费类电子产品的制造 本小类包括用于家庭娱乐、机动车、扩音系统和乐器功放的电子音频和视频设备的制造。 一卡式录像机和视频复制设备的制造； 一电视机的制造； 一电视监视器和显示器的制造； 一音频录制和复制系统的制造； 一立体声设备的制造； 一无线电接收机的制造； 一扬声器系统的制造； 一家用摄像机的制造； 一自动点唱机的制造； 一用于乐器和扩音系统的扩音设备的制造； —麦克风的制造； —CD和DVD播放机的制造； 一卡拉OK机的制造； 一耳机(如收音机、立体音响、计算机)的制造； 一视频游戏机的制造。 一已录制媒介(计算机媒介、声音、视频等)的复制，见09.02; 一计算机外部设备和电脑显示器的制造，见19.02.00; 一电话答录机的制造，见19.03.00; 一寻呼设备的制造，见19.03.00; 一 远 程 控 制 装 置 ( 无 线 电 和 红 外 线 ) 的 制 造 ，见19.03.00; 一播音室设备的制造，如复制设备、发射和接收天线、商用摄像机，见19.03.00; 一天线的制造，见19.03.00; —数码相机的制造，见19.07.00; — 带固定(不可更换)软件的电子游戏的制造，见23.05.00。"
