    "text_unit": "19 19.05 19.05.02 钟表的制造 本小类包括钟表和计时机械装置及其部件的制造。 一各类钟表的制造，包括仪表盘钟； 一钟表壳的制造，包括贵金属壳； 一计时设备，以及测量、记录和其他带钟表机芯或同步电动机并显示时间间隔的设备的制造，如： ◆停车计时器； ◆打卡机； ◆时间/日期章； ◆过程计时器。 一带钟表机芯或带同步电动机的计时开关和其他解锁装置的制造： ◆定时锁。 一钟表部件的制造： ◆各类钟表机芯； ◆发条、宝石、表盘、指针、夹板、支架和其他部件； ◆所有材料的钟表外壳和机架。 一 非金属(如织物、皮革、塑料)表带的制造，见05.01.02; —贵金属表带的制造，见23.02.02; 一非贵金属表带的制造，见23.02.03。"
