    "text_unit": "19 19.10 19.10.00 电池和蓄电池的制造 本小类包括不可充电及可充电电池的制造。 一原电池及原电池组的制造： ◆含有二氧化锰、二氧化汞、氧化银等的电池。 —蓄电池及其零部件的制造： ◆隔板、容器、包裹层。 一铅酸电池的制造； 一镍镉电池的制造； 一镍氢电池的制造； 一锂电池的制造； 一干电池的制造； 一湿电池的制造。"
