    "text_unit": "19 19.11 19.11.02 其他电线电缆的制造 一由钢、铜、铝制成的绝缘电线电缆的制造。 一金属线的制造(拉丝),见17.03.04、17.04.01~17.04.05; 一计算机线缆，打印机线缆，USB线缆和类似线缆或组件的制造，见19.01.01; 一带绝缘电线和连接器的电气套件的制造 ，见19.14.00; 一汽车用线缆、线束和类似电缆套件或组件的制造，见22.03.01。"
