    "text_unit": "19 19.12 19.12.00 电气照明设备的制造 本小类包括电灯泡、灯管部件与组件(电灯泡玻璃毛坯除外)以及电力照明灯具及其组件(载流配线装置除外)的制造。 一放电灯、白炽灯、荧光灯、紫外线灯、红外线灯等灯管、灯具和灯泡的制造； 一顶棚照明灯具的制造； 一 吊灯的制造； 一台灯(即灯具)的制造； 一圣诞树灯饰的制造； 一电壁炉丝的制造； —手电筒的制造； 一电杀虫灯的制造； 一提灯(如碳化物、电、气、汽油、煤油灯)的制造； 一聚光灯的制造； 一道路照明装置(交通信号灯除外)的制造； 一运输设备上(如汽车、飞机、船舶)照明装置的制造。 一非电力照明设备的制造。 一灯具玻璃及玻璃部件的制造，见15.01.05; 一灯具载流配线装置的制造，见19.11.03; 一集成了灯具的吊扇或浴室风扇的制造，见19.13.01 一电信号设备，如交通信号灯和人行道信号设备的制造，见19.14.00; 一电标识的制造，见19.14.00。"
