    "name": "床垫的制造",
    "text_unit": "23 23.01 23.01.03 床垫的制造 一床垫的制造： ◆装有弹簧、填充或内部装有支撑材料的床垫； ◆裸露的泡沫橡胶或泡沫塑料床垫。 一床垫支架的制造。 一充气橡胶床垫的制造，见14.01.02; 一橡胶水床床垫的制造，见14.01.02。"
