    "text_unit": "23 23.01 23.01.04 其他家具的制造 一沙发、沙发床、组合沙发的制造； —花园座椅和座位的制造； 一卧室、起居室和花园等处的家具的制造； 一缝纫机、电视机等用橱柜的制造。 —如椅子和座位装饰(装软垫)等后加工； 一家具的后加工，如喷漆、油漆、表面抛光和装饰(装软垫)等。 一枕头、褥子、坐垫、棉被和绒被的制造，见04.04.02; 一陶瓷、混凝土和石制家具的制造，见15.04.02、 16.02.06、15.05.00; 一照明装置或灯具的制造，见19.12.00; 一汽车座椅的制造，见22.03.02; 一火车座椅的制造，见22.04.00; 一飞机座椅的制造，见21.01.00; —家具的重新装饰(装软垫)及修复，见29.22.04。"
