    "text_unit": "23 23.02 23.02.03 仿真首饰及相关物品的制造 一仿真珠宝首饰的制造： ◆镀有贵金属的基础金属戒指、手镯、项链和类似饰品 ◆含有如仿真宝石、仿真钻石及类似品的首饰。 一金属表带的制造(贵金属表带除外)。 一贵金属或包有贵金属的基础金属首饰的制造，见23.02.02; 一含有真宝石的首饰的制造，见23.02.02; 一贵金属表带的制造，见23.02.02。"
