    "name": "游戏用品及玩具的制造",
    "text_unit": "23 23.05 23.05.00 游戏用品及玩具的制造 本小类包括玩偶、玩具和游乐用品(包括电子游戏机)、成比例模型和童车(金属自行车和三轮车除外)的制造。 一玩偶和玩偶服装、部件和配件的制造； 一可动人形的制造； 一玩具动物的制造； 一玩具乐器的制造； 一纸牌的制造； 一棋类和类似游戏的制造； 一电子游戏机(不可更换游戏内容)的制造：国际象棋 等 ； 一缩小尺寸(“成比例缩小”)模型和类似娱乐模型、电动火车、成套建筑模型等的制造； 一投币游戏机、台球桌、卡西诺专用游戏桌等的制造； 一游乐场、桌上或室内游戏物品的制造； 一供乘骑的有轮玩具，包括塑料自行车和三轮车的制造； 一智力玩具及类似物品的制造。 —视频游戏机的制造，见19.04.00; 一自行车的制造，见22.05.02; 一逗乐物品和新奇小物品的制造，见23.07.02; 一视频游戏机软件的编写和发行 见33 01 01 33 02 01"
