    "name": "医疗及牙科器械和用品的制造",
    "text_unit": "23 23.06 23.06.00 医疗及牙科器械和用品的制造 本小类包括实验室器材、手术及医疗器械、手术器具和用品、牙科设备和用品、牙齿矫正物品、假牙及矫正器具的制造。本小类还包括医疗、牙科用家具及类似家具的制造，这些家具附带的特定功能决定了此类产品的用途，例如内置液压功能的牙医用椅。 一手术用消毒帷帘、无菌线和纱的制造； 一补牙材料和牙科用粘固剂的制造(假牙粘合剂除外)、牙科用蜡及其他牙科石膏制剂的制造； 一骨骼重构粘固剂的制造； 一牙科实验室用炉的制造； 一实验室超声清洗机的制造； 一实验室用消毒器的制造； 一实验室型蒸馏装置、实验室离心机的制造； 一医疗、外科、牙科或兽医用家具的制造，如： ◆手术台； ◆检查台； ◆配有机械装置的医院病床； ◆牙医用椅。 一接骨板、接骨螺钉、注射器、针头、导尿管、医疗用套管等的制造； 一牙科器械(包括装有牙科设备的牙医用椅)的制造； 一人造牙、桥托(牙)等在牙科实验室制成的物品的制造； —整形和修复设备的制造； 一玻璃眼的制造； 一医用温度计的制造； 一眼科用品、眼镜、太阳镜、处方镜片、隐形眼镜、护目镜的制造。 一假牙粘合剂的制造，见12.04.02; 一医疗浸药填料、敷料等的制造，见13.02.00; 一电子医学及电子治疗设备的制造，见19.06.00; 一轮椅的制造，见22.05.02; 一配镜师的活动，见29.19.08。"
