    "text_unit": "31 31.13 31.13.01 陆路运输附属的服务活动 本小类包括： 一陆路运输旅客、动物或货物有关活动： 车站设施(如火车站、汽车站、货运站)的运营； 铁路基础设施的运营； 道路、桥梁、隧道、停车场或车库、自行车停车 场、篷车的冬季存放库等设施的运营。 一换道与调车； 一拖带和公路救援。 本小类还包括： 一以运输为目的气体的液化； 一货物装卸，见31.13.04。"
