    "text_unit": "31 31.19 31.19.00 其他电信活动 本小类包括： 一提供专业通信应用，如卫星跟踪、遥测通信、雷达 站操作 ； 一卫星终端站和相关设施的运营，操作中连接一个或 多个地面通信系统，并且有能力向卫星系统传送或 接收信息； 一在终端用户和互联网接入服务商之间提供互联网接 入服务，这种接入不由互联网接入服务商拥有或控 制，如拨号上网等； 一面向公众开放的电话和互联网接入设施的运营； 一通过现有的电信连接提供电信服务： ◆VOIP(互联网语音电话)的提供。 一电信经销商(即购买和转售网路带宽而不提供附加 服务)。 一运营通信基础设施，提供互联网接入，见31.16～31.18。"
