    "name": "会计、簿记及审计活动，税务咨询",
    "text_unit": "35 35.02 35.02.00 会计、簿记及审计活动，税务咨询 本小类包括： 一来自商业或其他形式的贸易记录； 一财务账目的准备与审计； 一账目的检查及其准确性的证明； 一个人或企业所得税申报单的准备； 一(税务)咨询活动以及在税务机构作为客户的代理。 —数据处理和制表活动，见33.03.01; 一会计系统、预算控制程序的管理咨询，见35.04.02 一票据托收，见35.21.01。"
